export const code = async (inputs) => {
  const p = typeof inputs.payload === 'string' ? JSON.parse(inputs.payload) : inputs.payload;
  const name = (p.name || p.student_name || '').trim();
  const phone = (p.phone || p.parent_phone || '').trim();
  const email = (p.email || p.parent_email || '').trim();
  const valid = name.length > 0 && (phone.length > 0 || email.length > 0);
    const dupCheck = name.length > 0 && phone.length > 0 ? { name, phone } : null;
  return {
    valid: valid,
    student_name: name,
    student_age: p.age || p.student_age || '',
    student_level: p.level || p.student_level || 'beginner',
    parent_name: p.parent_name || name + "'s Parent",
    parent_phone: phone,
    parent_email: email,
    entity: p.entity || 'tots-tennis',
    batch_id: p.batch_id || '',
    coach_id: p.coach_id || '',
    plan_type: p.plan_type || 'Monthly',
    amount: parseInt(p.amount || '0'),
    start_date: p.start_date || new Date().toISOString().split('T')[0],
    error: valid ? '' : 'Missing required fields: name and at least phone or email'
  };
};

